import * as fs from "fs";
import * as path from "path";
import type { VercelRequest, VercelResponse } from "@vercel/node";

// GET /api/train?theme=dark|light  -> looping pixel-art Series 0 Shinkansen (generated by scripts/train.py)
export default function handler(req: VercelRequest, res: VercelResponse) {
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
    if (req.method === "OPTIONS") {
        res.status(200).end();
        return;
    }

    const { theme = "light" } = req.query;
    const file = theme === "dark" ? "train_dark.svg" : "train_light.svg";
    const svg = fs.readFileSync(path.join(process.cwd(), "resources/svg", file), "utf8");

    res.setHeader("Content-Type", "image/svg+xml");
    res.setHeader("Cache-Control", "public, max-age=86400, s-maxage=86400");
    res.send(svg);
}
